                          onChange={handleCustomerChange}
                          disabled={isLoading}
                      />
                      <button
                          type="button"
                          className="absolute inset-y-0 right-0 pr-3 flex items-center"
                          onClick={toggleConfirmPasswordVisibility}
                      >
                        {showConfirmPassword ? (
                            <EyeOff className="h-4 w-4 text-gray-400" />
